sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
if (isLoading || !newValue) {
        // Clear fine amount if the reference field is emptied
        if (!newValue) {
            g_form.setValue('fine_amount', '');
        }
        return;
    }

    // Fetch the entire referenced record from the Violation Type table
    g_form.getReference('violation_type', function(violationGr) {
        if (violationGr && violationGr.fine_amount) {
            // Set the fine amount on the Citation table form
            g_form.setValue('fine_amount', violationGr.fine_amount);
        }
    });

}
